phase1.code:
use std::time::Duration;

// ---- Tokio runtime setup ----
// Add to Cargo.toml:
// [dependencies]
// tokio = { version = "1.0", features = ["full"] }

// ---- Running async main with Tokio ----
#[tokio::main]
async fn main() {
    println!("=== Tokio Runtime ===");

    // ---- Basic async task ----
    let result = hello().await;
    println!("{}", result);

    // ---- Async sleep ----
    println!("Sleeping for 1 second...");
    tokio::time::sleep(Duration::from_secs(1)).await;
    println!("Done sleeping!");

    // ---- Concurrent tasks ----
    let task1 = tokio::spawn(async {
        tokio::time::sleep(Duration::from_millis(200)).await;
        "Task 1 complete"
    });

    let task2 = tokio::spawn(async {
        tokio::time::sleep(Duration::from_millis(100)).await;
        "Task 2 complete"
    });

    let result1 = task1.await.unwrap();
    let result2 = task2.await.unwrap();
    println!("Results: {}, {}", result1, result2);

    // ---- Multiple tasks with join ----
    let tasks = vec![
        tokio::spawn(async {
            tokio::time::sleep(Duration::from_millis(150)).await;
            "A"
        }),
        tokio::spawn(async {
            tokio::time::sleep(Duration::from_millis(50)).await;
            "B"
        }),
        tokio::spawn(async {
            tokio::time::sleep(Duration::from_millis(100)).await;
            "C"
        }),
    ];

    for task in tasks {
        let result = task.await.unwrap();
        println!("Task result: {}", result);
    }

    // ---- Tokio with error handling ----
    let result = fetch_data().await;
    match result {
        Ok(data) => println!("Fetched: {}", data),
        Err(e) => println!("Error: {}", e),
    }
}

// ---- Async function ----
async fn hello() -> String {
    "Hello, Tokio!".to_string()
}

// ---- Async function with error ----
async fn fetch_data() -> Result<String, &'static str> {
    tokio::time::sleep(Duration::from_millis(100)).await;
    Ok("Data from network".to_string())
}

